package com.huy.enterprise.supplier; import com.huy.enterprise.common.enums.*; import jakarta.validation.constraints.*; import java.util.UUID; record SupplierRequest(@NotBlank String supplierCode,@NotBlank String name,@Email String email,String phone,String address,String country,String region,RecordStatus status,RiskLevel riskLevel,String notes){} record SupplierResponse(UUID id,String supplierCode,String name,String email,String phone,String address,String country,String region,RecordStatus status,RiskLevel riskLevel,String notes){static SupplierResponse from(Supplier s){return new SupplierResponse(s.getId(),s.getSupplierCode(),s.getName(),s.getEmail(),s.getPhone(),s.getAddress(),s.getCountry(),s.getRegion(),s.getStatus(),s.getRiskLevel(),s.getNotes());}}
